		fmt.Fprintf(w, "%-*s %-*s %-13s %-*s %s\n",
			branchWidth, t.Branch,
			trailTitleColumnWidth, title,
			t.Status,
			trailAuthorColumnWidth, stringutil.TruncateRunes(t.AuthorLogin(), trailAuthorColumnWidth, "..."),
			timeAgo(t.UpdatedAt))
	}
}

func newTrailCreateCmd() *cobra.Command {
	var title, body, base, branch, status string
	var checkout bool

	cmd := &cobra.Command{
