func limitTrails(trails []*trail.Metadata, limit int) []*trail.Metadata {
	if len(trails) <= limit {
		return trails
	}
	return trails[:limit]
}

func filterTrailsByAuthor(trails []*trail.Metadata, login string) []*trail.Metadata {
	var filtered []*trail.Metadata
	for _, t := range trails {
		if t.AuthorLogin() == login {
			filtered = append(filtered, t)
		}
	}
	return filtered
}

type currentUserResponse struct {
	Login    string `json:"login"`
	Username string `json:"username"`
	User     struct {
		Login    string `json:"login"`
		Username string `json:"username"`
	} `json:"user"`
}

func (r currentUserResponse) login() string {
	for _, candidate := range []string{r.Login, r.Username, r.User.Login, r.User.Username} {
		if candidate != "" {
