package cli

import (
	"bytes"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/trail"
)

func TestLimitTrailsKeepsMostRecentPrefix(t *testing.T) {
	trails := []*trail.Metadata{
		{Branch: "newest"},
		{Branch: "middle"},
		{Branch: "oldest"},
	}

	got := limitTrails(trails, 2)
	if len(got) != 2 {
		t.Fatalf("len = %d, want 2", len(got))
	}
	if got[0].Branch != "newest" || got[1].Branch != "middle" {
		t.Fatalf("got branches %q, %q; want newest, middle", got[0].Branch, got[1].Branch)
	}

	if all := limitTrails(trails, 0); len(all) != len(trails) {
		t.Fatalf("limit 0 len = %d, want %d", len(all), len(trails))
	}
}

func TestPrintTrailListTableDoesNotTruncateBranch(t *testing.T) {
	longBranch := "feature/very-long-branch-name-that-must-remain-visible"
	longTitle := "This title is intentionally very long so the title column is truncated instead"

	var out bytes.Buffer
	printTrailListTable(&out, []*trail.Metadata{
		{
			Branch:    longBranch,
			Title:     longTitle,
			Status:    trail.StatusOpen,
			UpdatedAt: time.Now(),
		},
	})

	text := out.String()
	if !strings.Contains(text, longBranch) {
		t.Fatalf("output should contain full branch %q, got:\n%s", longBranch, text)
	}
	if strings.Contains(text, longTitle) {
		t.Fatalf("output should truncate long title, got:\n%s", text)
	}
	if !strings.Contains(text, "...") {
		t.Fatalf("output should show truncation suffix, got:\n%s", text)
	}
}

