func printTrailListTable(w io.Writer, trails []*trail.Metadata) {
	branchWidth := len("BRANCH")
	for _, t := range trails {
		if width := len([]rune(t.Branch)); width > branchWidth {
			branchWidth = width
		}
	}
	titleWidth := trailTitleColumnWidth
	if branchWidth+1+titleWidth > trailBranchTitleTotalWidth {
		titleWidth = trailBranchTitleTotalWidth - 1 - branchWidth
		if titleWidth < trailMinTitleColumnWidth {
			titleWidth = trailMinTitleColumnWidth
		}
	}

	fmt.Fprintf(w, "%-*s %-*s %-13s %-*s %s\n",
		branchWidth, "BRANCH",
		titleWidth, "TITLE",
		"STATUS",
		trailAuthorColumnWidth, "AUTHOR",
		"UPDATED")
	for _, t := range trails {
		title := stringutil.TruncateRunes(t.Title, titleWidth, "...")
		fmt.Fprintf(w, "%-*s %-*s %-13s %-*s %s\n",
			branchWidth, t.Branch,
			titleWidth, title,
			t.Status,
			trailAuthorColumnWidth, stringutil.TruncateRunes(t.AuthorLogin(), trailAuthorColumnWidth, "..."),
			timeAgo(t.UpdatedAt))
	}
}

