func trailStatusTitle(status trail.Status) string {
	display := trailStatusDisplay(status)
	if display == "" {
		return ""
	}
	return strings.ToUpper(display[:1]) + display[1:]
}

func pluralize(s string, count int) string {
	if count == 1 {
		return s
	}
	return s + "s"
}

